// Extract URLs from SerpAPI organic results
const results = $input.first().json.items|| [];
const query = $input.first().json.search_parameters?.q || '';

return results.map((result, index) => ({
  url: result.link,
  title: result.title || '',
  snippet: result.snippet || '',
  position: index + 1,
  query_source: query
}));

const inputUrl = $input.first().json.url;

// Extract protocol://domain:port
const match = inputUrl.match(/^(https?:\/\/[^\/\?#]+)/i);
const rootUrl = match ? match[1] : null;

return {
  json: {
    originalUrl: inputUrl,
    rootUrl: rootUrl
  }
};

const xml =$input.first().json.data
// Extract all URLs between <loc> tags
const locPattern = /<loc>(.*?)<\/loc>/g;
const sitemapUrls = [];
let match;

while ((match = locPattern.exec(xml)) !== null) {
  sitemapUrls.push(match[1]);
}

// Return as separate items for n8n to process
return sitemapUrls.map(sitemapUrl => ({
  json: {
    sitemapUrl: sitemapUrl,
    type: getSitemapType(sitemapUrl)
  }
}));

function getSitemapType(sitemapUrl) {
  if (sitemapUrl.includes('products')) return 'products';
  if (sitemapUrl.includes('pages')) return 'pages';
  if (sitemapUrl.includes('collections')) return 'collections';
  if (sitemapUrl.includes('blogs')) return 'blogs';
  return 'other';
}

const html =$input.first().json.data

function extractBySection(html) {
  const sections = {
    header: '',
    footer: '',
    main: '',
    contact: '',
    about: '',
    url: $('Check if Root URL').first().json.rootUrl
  };

  // Extract header
  const headerMatch = html.match(/<header[\s\S]*?<\/header>/gi);
  if (headerMatch) sections.header = cleanHTML(headerMatch[0]);

  // Extract footer
  const footerMatch = html.match(/<footer[\s\S]*?<\/footer>/gi);
  if (footerMatch) sections.footer = cleanHTML(footerMatch[0]);

  // Extract main content
  const mainMatch = html.match(/<main[\s\S]*?<\/main>/gi);
  if (mainMatch) sections.main = cleanHTML(mainMatch[0]);

  // Extract contact sections
  const contactPatterns = [
    /<[^>]*class=["'][^"']*contact[^"']*["'][^>]*>[\s\S]*?<\/[^>]+>/gi,
    /<[^>]*id=["'][^"']*contact[^"']*["'][^>]*>[\s\S]*?<\/[^>]+>/gi,
    /<section[^>]*>[\s\S]*?contact[\s\S]*?<\/section>/gi
  ];

  contactPatterns.forEach(pattern => {
    const matches = html.match(pattern);
    if (matches) {
      sections.contact += ' ' + matches.map(m => cleanHTML(m)).join(' ');
    }
  });

  // Extract about sections
  const aboutPatterns = [
    /<[^>]*class=["'][^"']*about[^"']*["'][^>]*>[\s\S]*?<\/[^>]+>/gi,
    /<[^>]*id=["'][^"']*about[^"']*["'][^>]*>[\s\S]*?<\/[^>]+>/gi
  ];

  aboutPatterns.forEach(pattern => {
    const matches = html.match(pattern);
    if (matches) {
      sections.about += ' ' + matches.map(m => cleanHTML(m)).join(' ');
    }
  });

  // If no specific sections found, use whole body
  if (!sections.header && !sections.footer && !sections.main) {
    const bodyMatch = html.match(/<body[\s\S]*?<\/body>/gi);
    if (bodyMatch) sections.main = cleanHTML(bodyMatch[0]);
  }

  return sections;
}

function cleanHTML(html) {
  let text = html;

  // Remove non-visible elements
  text = text.replace(/<script[\s\S]*?<\/script>/gi, '');
  text = text.replace(/<style[\s\S]*?<\/style>/gi, '');
  text = text.replace(/<!--[\s\S]*?-->/g, '');

  // Preserve structure
  text = text.replace(/<br[^>]*>/gi, '\n');
  text = text.replace(/<\/?(p|div|h[1-6]|li)[^>]*>/gi, '\n');

  // Remove tags
  text = text.replace(/<[^>]+>/g, ' ');

  // Decode entities
  text = text.replace(/&nbsp;/g, ' ')
             .replace(/&amp;/g, '&')
             .replace(/&lt;/g, '<')
             .replace(/&gt;/g, '>')
             .replace(/&quot;/g, '"')
             .replace(/&#39;/g, "'")
             .replace(/&[#\w]+;/g, ' ');

  // Clean whitespace
  text = text.replace(/\n\s*\n+/g, '\n')
             .replace(/[ \t]+/g, ' ')
             .trim();

  return text;
}

const sections = extractBySection(html);

// Combine sections prioritizing contact-relevant areas
const combinedText = [
  sections.contact,
  sections.footer,
  sections.about,
  sections.header,
  sections.main
].filter(s => s.length > 0).join('\n\n---\n\n');

return {
  json: {
    sections: sections,
    combinedText: combinedText,
    contactPriority: sections.contact || sections.footer || sections.main
  }
};

