function isContactRelevant(pageUrl) {
  const lowerUrl = pageUrl.toLowerCase();

  // Always include homepage
  if (lowerUrl.match(/^https?:\/\/[^\/]+\/?$/)) {
    return true;
  }

  // Contact-relevant keywords
  const relevantKeywords = [
    "contact",
    "about",
    "support",
    "help",
    "reach",
    "location",
    "store",
    "info",
    "team",
    "company",
    "our-story",
    "who-we-are",
    "get-in-touch",
    "faq",
    "customer-service",
    "pages/contact",
    "pages/about",
  ];

  const hasRelevantKeyword = relevantKeywords.some((keyword) =>
    lowerUrl.includes(keyword)
  );

  // Exclude non-contact pages
  const excludePatterns = [
    /\/products?\//,
    /\/collections?\//,
    /\/cart/,
    /\/checkout/,
    /\/account/,
    /\/search/,
    /\/blogs?\//,
    /\/password/,
    /\/login/,
  ];

  const isExcluded = excludePatterns.some((pattern) => pattern.test(lowerUrl));

  return hasRelevantKeyword && !isExcluded;
}

const xml = $input.first().json.data;

// Extract all URLs
const urlPattern = /<url>[\s\S]*?<loc>(.*?)<\/loc>[\s\S]*?<\/url>/g;
const item = $("Check if Root URL").first().json.originalUrl;
const pageUrls = [];
pageUrls.push({ url: item });
let match;
while ((match = urlPattern.exec(xml)) !== null) {
  if (isContactRelevant(match[1])) {
    pageUrls.push({ url: match[1] });
  }
}

// Return as a SINGLE item containing the array
return pageUrls;
